export const investmentBorrowingDefinitions={
 investmentLoan:{title:'Compare investing with and without an interest-only loan using matched household cash',fields:[
  ['loan','Hypothetical investment loan principal (CAD)',50000,0,200000,5000],['borrowingRate','Annual simple interest rate, paid monthly (%)',7,0,15,.5],
  ['surplusMonthly','Monthly investing cash after the borrowing case pays interest (CAD)',100,0,2000,50],
  ['investmentReturn','Hypothetical effective annual investment total return (%)',5,-15,15,.5],['years','Whole years before sale and principal repayment',10,1,20,1]
 ]}
};
export function investmentBorrowingPlan(d){
 const interestMonthly=d.loan*d.borrowingRate/1200,budget=interestMonthly+d.surplusMonthly,q=(1+d.investmentReturn/100)**(1/12)-1,n=12*d.years;
 let borrowedAsset=d.loan,plainAsset=0,borrowedGain=0,plainGain=0;
 const rows=[{x:0,borrowedAsset,plainAsset,borrowedNet:0}];
 for(let month=1;month<=n;month++){
  const a=borrowedAsset*q,b=plainAsset*q;borrowedGain+=a;plainGain+=b;
  borrowedAsset+=a+d.surplusMonthly;plainAsset+=b+budget;
  rows.push({x:month,borrowedAsset,plainAsset,borrowedNet:borrowedAsset-d.loan});
 }
 const borrowedNet=borrowedAsset-d.loan,interestTotal=interestMonthly*n,borrowedContributions=d.surplusMonthly*n,plainContributions=budget*n;
 return {rows,interestMonthly,budget,interestTotal,borrowedAsset,plainAsset,borrowedNet,borrowedGain,plainGain,borrowedContributions,plainContributions,difference:borrowedNet-plainAsset,equivalentAnnual:(1+d.borrowingRate/1200)**12-1};
}
export function investmentBorrowingResult(kind,d){
 if(kind!=='investmentLoan')throw Error('Unknown investment-borrowing topic.');
 const p=investmentBorrowingPlan(d);
 return {metrics:[['Monthly household cash required in each case',p.budget,'money'],['Borrowing case: investment less loan at the end',p.borrowedNet,'money'],['Borrowing minus no-borrowing ending net position',p.difference,'money']],note:'Two invented scenarios start with zero own-money investment equity. One borrows the selected principal and invests it immediately; the other borrows nothing. Both receive the same monthly household cash: the loan’s monthly interest plus the selected extra investing cash. The borrowing case pays interest from that budget and invests the remainder; the no-loan case invests the whole budget. All deposits arrive at month-end after growth. Loan principal stays unchanged until repayment at the final date; interest is fully paid monthly and never capitalized. Both investments receive the same constant effective annual total-return assumption, converted to monthly factors. All distributions are reinvested. There are no fees, taxes, interest deductions, collateral calls, forced sales, borrowing limits or changes in rates. Availability of the derived monthly cash and the loan is assumed, not assessed. Negative investment-minus-debt values remain liabilities requiring another repayment source. This narrow matched-cash calculation cannot determine suitability or reproduce an actual lending contract.',charts:[
  {id:'investment-loan-net-paths',type:'line',title:'Compare investment equity after subtracting the outstanding loan',unit:'money',xLabel:'Completed monthly periods',series:[{name:'Borrowing case: investment value less unchanged loan',rows:p.rows.map(r=>({x:r.x,value:r.borrowedNet}))},{name:'No borrowing: investment value, with no loan',dash:true,rows:p.rows.map(r=>({x:r.x,value:r.plainAsset}))}],note:'The borrowed investment begins larger, but its opening asset and debt offset to zero equity. Each line receives the same household cash budget over time. The loan is deducted once to show the borrowing case’s net position; the line is not its gross brokerage balance.'},
  {id:'investment-loan-repayment-bridge',type:'waterfall',title:'Reconcile the borrowing case’s assets and final principal repayment',unit:'money',rows:[{label:'Opening investment funded by loan',value:d.loan},{label:'New household money invested after interest',value:p.borrowedContributions},{label:'Investment growth or loss',value:p.borrowedGain},{label:'Unchanged loan principal repaid at the end',value:-d.loan}],totalLabel:'Net position after principal repayment',note:'Interest was paid from the matched monthly household budget and reduced the cash available for new investment. It is shown in the budget chart, not subtracted again from this asset-and-debt bridge. This endpoint is remaining net resources, not profit relative to household contributions.'},
  {id:'investment-loan-cash-budget',type:'stackbar',title:'Allocate the same total household cash between interest and investing',unit:'money',seriesNames:['Interest paid from household cash','New household cash invested'],rows:[{label:'Borrow and invest',values:[p.interestTotal,p.borrowedContributions]},{label:'Invest without borrowing',values:[0,p.plainContributions]}],note:'Both bars total the same cumulative household cash. Initial borrowed principal is financing, not an extra own-money contribution. The borrowing case’s investment asset is separate from these household cash allocations, and the original loan must still be repaid.'},
  {id:'investment-loan-rate-matrix',type:'heatmap',title:'Ending net-position difference across borrowing costs and investment returns',unit:'money',signed:true,unitLabel:'CAD · borrowing minus no borrowing; rows: annual loan interest; columns: annual investment return',columns:[-10,0,5,10].map(x=>x+'%'),rows:[0,3,7,12].map(borrowingRate=>({label:borrowingRate+'% loan',values:[-10,0,5,10].map(investmentReturn=>investmentBorrowingPlan({...d,borrowingRate,investmentReturn}).difference)})),note:'Every cell matches the two cases’ monthly household cash using that row’s interest payment plus the selected extra investing cash. The derived common budget therefore changes between loan-rate rows. Principal, extra investing cash and horizon remain selected. Positive differences are conditional arithmetic, not forecasts, probabilities or suitability findings.'}
 ]};
}
